cd /workspace/tmp_tests && python3 - << 'PYEOF'
import sys, json; sys.path.insert(0,'/workspace/tmp_tests')
from harness import ok, bad
P=[{"id":"p","max_aliases":1,"cname":"follow","wildcard":"rfc"}]
def D(recs, q=None):
    return {"zones":[{"origin":"test.","records":recs}],"profiles":P,
            "queries":q or [{"id":"q","name":"a.test.","type":"AAAA","cost":1}],"observations":[]}

# AAAA canonicalization
r=ok(D([{"owner":"a.test.","type":"AAAA","data":"2001:0DB8:0000:0000:0000:0000:0000:0001"}]))
print('aaaa canon', r['runs'][0]['answer'])
r=ok(D([{"owner":"a.test.","type":"AAAA","data":"::FFFF:192.0.2.1"}]))
print('v4-mapped', r['runs'][0]['answer'])
for badv in ["fe80::1%eth0","1.2.3.4","::1%","0:0:0:0:0:0:0","12345::","::g"," ::1","::1 ","-1::","::1.2.3.04"]:
    try:
        ok(D([{"owner":"a.test.","type":"AAAA","data":badv}])); print('!!! ACCEPTED bad AAAA', repr(badv))
    except AssertionError: print('rejected AAAA', repr(badv))
# TXT
for t,c in [("",True),("~",True),("\x7f",False),("\x1f",False),("x"*256,True),("x"*257,False),("a\"b\\c",True),("\u00e9",False)]:
    doc={"zones":[{"origin":"test.","records":[{"owner":"a.test.","type":"TXT","data":t}]}],"profiles":P,
         "queries":[{"id":"q","name":"a.test.","type":"TXT","cost":1}],"observations":[]}
    try:
        r=ok(doc); got = r['runs'][0]['answer'][0]['data']==t
        print('TXT ok len=%d accepted=%s preserved=%s'%(len(t),True,got)); assert c and got
    except AssertionError as e:
        print('TXT len=%d accepted=False expected=%s'%(len(t),c)); assert not c
# A
for v,c in [("0.0.0.0",True),("255.255.255.255",True),("256.0.0.0",False),("00.0.0.0",False),("0.0.0.0.",False),("1.2.3",False),("1.2.3.4.5",False),("+1.2.3.4",False),("1.2.3.4 ",False),("010.2.3.4",False)]:
    doc={"zones":[{"origin":"test.","records":[{"owner":"a.test.","type":"A","data":v}]}],"profiles":P,
         "queries":[{"id":"q","name":"a.test.","type":"A","cost":1}],"observations":[]}
    try:
        ok(doc); assert c, ('accepted but should reject', v); print('A ok', v)
    except AssertionError as e:
        assert not c, ('rejected but valid', v, e); print('A rejected', repr(v))
# id case sensitivity + name case canonicalization
doc={"zones":[{"origin":"TEST.","records":[{"owner":"A.TEST.","type":"A","data":"192.0.2.1"}]}],"profiles":[{"id":"P","max_aliases":1,"cname":"follow","wildcard":"rfc"},{"id":"p","max_aliases":1,"cname":"follow","wildcard":"rfc"}],
     "queries":[{"id":"Q","name":"a.TeSt.","type":"A","cost":1}],"observations":[{"id":"O","query":"Q","profile":"P","result":{"status":"response","rcode":"NOERROR","answer":[{"owner":"A.test.","type":"A","data":"192.0.2.1"}]}}]}
r=ok(doc); print(r['runs'][0], r['audits'], r['diagnostic'])
PYEOF
